//! Zero-JSON Rust `nve-dioxus` + `nve-abi` binary emitter for `import_rn`.

mod types;

use std::fmt::Write as _;

use crate::naming::{
    escape_c_like_string, rust_ident, sanitize_single_line_comment, strip_on_prefix,
    to_pascal_case, to_snake_case,
};
use crate::schema::export::{RnComponentSpec, TurboModuleSpec};
use types::*;

pub(crate) fn emit_component_rust(spec: &RnComponentSpec, mod_name: &str) -> String {
    let pascal = to_pascal_case(&spec.component_name);
    let mut out = String::with_capacity(4096);

    let _ = writeln!(
        out,
        "// @generated by nve-codegen (`import_rn`) from React Native Fabric component `{}`.",
        sanitize_single_line_comment(&spec.component_name)
    );
    let _ = writeln!(
        out,
        "// Zero-JS, zero-JSON typed Rust `nve-dioxus` bindings + `nve-abi` binary prop builders."
    );
    let _ = writeln!(out);
    let _ = writeln!(out, "#![allow(dead_code, clippy::all)]");
    let _ = writeln!(out);
    let _ = writeln!(out, "pub mod {mod_name} {{");
    let _ = writeln!(
        out,
        "    use nve_abi::{{encode_bin_value_to_vec, BinValueView, ColorRgba, CommandBufferBuilder, ComponentKind, EventMask, EventPayload, NativeEvent, NativeEventKind, NodeId, NveMapEntry, NveValue, RawPropValue}};"
    );
    let _ = writeln!(out, "    use nve_dioxus::elements::AttributeDescription;");
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "    /// React Native Fabric component name registered in the native host."
    );
    let _ = writeln!(
        out,
        "    pub const COMPONENT_NAME: &str = \"{}\";",
        escape_c_like_string(&spec.component_name)
    );
    let _ = writeln!(out, "    pub const TAG_NAME: &'static str = COMPONENT_NAME;");
    let _ = writeln!(out, "    pub const NAME_SPACE: Option<&'static str> = None;");
    if let Some(paper) = &spec.options.paper_component_name {
        let _ = writeln!(
            out,
            "    pub const PAPER_COMPONENT_NAME: &str = \"{}\";",
            escape_c_like_string(paper)
        );
    }
    let _ = writeln!(out);

    // 1. Emit auxiliary enums/structs for enum & object props
    for prop in &spec.props {
        emit_rust_aux_types(
            &mut out,
            &pascal,
            &prop.name,
            &prop.prop_type,
            prop.default_value.as_ref(),
        );
    }

    // 2. Emit typed event payload structs + unified component event enum (binary NveBinValue)
    for ev in &spec.events {
        emit_rust_event_payload(&mut out, &pascal, ev);
    }

    if !spec.events.is_empty() {
        let _ = writeln!(out, "    #[derive(Debug, Clone, PartialEq)]");
        let _ = writeln!(out, "    pub enum {pascal}Event {{");
        for ev in &spec.events {
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            if ev.payload.is_empty() {
                let _ = writeln!(out, "        {variant},");
            } else {
                let payload_ty = format!("{pascal}{variant}Event");
                let _ = writeln!(out, "        {variant}({payload_ty}),");
            }
        }
        let _ = writeln!(out, "    }}");
        let _ = writeln!(out);

        let _ = writeln!(
            out,
            "    /// Decodes a `NativeEventKind::Custom` binary `NveBinValue` event emitted by `{}` into `{pascal}Event`.",
            sanitize_single_line_comment(&spec.component_name)
        );
        let _ = writeln!(
            out,
            "    pub fn decode_event(event: &NativeEvent) -> Option<{pascal}Event> {{"
        );
        let _ = writeln!(out, "        if event.kind != NativeEventKind::Custom {{");
        let _ = writeln!(out, "            return None;");
        let _ = writeln!(out, "        }}");
        let _ = writeln!(
            out,
            "        let EventPayload::Custom {{ name, data }} = &event.payload else {{"
        );
        let _ = writeln!(out, "            return None;");
        let _ = writeln!(out, "        }};");
        let _ = writeln!(out, "        match name.as_str() {{");
        for ev in &spec.events {
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            let short_name = strip_on_prefix(&ev.name);
            let pattern = if let Some(paper) = &ev.paper_top_level_name {
                format!(
                    "\"{}\" | \"{}\" | \"{}\"",
                    escape_c_like_string(&ev.name),
                    escape_c_like_string(&short_name),
                    escape_c_like_string(paper)
                )
            } else {
                format!(
                    "\"{}\" | \"{}\"",
                    escape_c_like_string(&ev.name),
                    escape_c_like_string(&short_name)
                )
            };
            if ev.payload.is_empty() {
                let _ = writeln!(
                    out,
                    "            {pattern} => Some({pascal}Event::{variant}),"
                );
            } else {
                let payload_ty = format!("{pascal}{variant}Event");
                let _ = writeln!(
                    out,
                    "            {pattern} => {payload_ty}::decode_bin(data).map({pascal}Event::{variant}),"
                );
            }
        }
        let _ = writeln!(out, "            _ => None,");
        let _ = writeln!(out, "        }}");
        let _ = writeln!(out, "    }}");
        let _ = writeln!(out);
    }

    // 3. Emit `dioxus_elements` attribute constants
    let _ = writeln!(out, "    /// Attribute descriptors for Dioxus `rsx!{{}}` templates.");
    let _ = writeln!(out, "    pub mod attrs {{");
    let _ = writeln!(out, "        use super::AttributeDescription;");
    if spec.extends_view_props {
        let _ = writeln!(
            out,
            "        pub const style: AttributeDescription = (\"style\", None, false);"
        );
        let _ = writeln!(
            out,
            "        pub const test_id: AttributeDescription = (\"testID\", None, false);"
        );
    }
    for prop in &spec.props {
        let ident = rust_ident(&prop.name);
        let _ = writeln!(
            out,
            "        #[allow(non_upper_case_globals)]\n        pub const {ident}: AttributeDescription = (\"{}\", None, false);",
            escape_c_like_string(&prop.name)
        );
    }
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out);

    // 4. Emit typed Dioxus event listener helpers
    if !spec.events.is_empty() {
        let _ = writeln!(out, "    /// Typed Dioxus event attribute constructors.");
        let _ = writeln!(out, "    pub mod events {{");
        let _ = writeln!(out, "        use super::*;");
        let _ = writeln!(
            out,
            "        use nve_dioxus::prelude::dioxus_core::{{Attribute, AttributeValue, Event}};"
        );
        for ev in &spec.events {
            let fn_name = rust_ident(&ev.name);
            let variant = to_pascal_case(&strip_on_prefix(&ev.name));
            let event_ty = if ev.payload.is_empty() {
                "Event<()>".to_owned()
            } else {
                format!("Event<{pascal}{variant}Event>")
            };
            let _ = writeln!(out);
            let _ = writeln!(
                out,
                "        pub fn {fn_name}(handler: impl FnMut({event_ty}) + 'static) -> Attribute {{"
            );
            let _ = writeln!(
                out,
                "            Attribute::new(\"{}\", AttributeValue::listener(handler), None, false)",
                escape_c_like_string(&ev.name)
            );
            let _ = writeln!(out, "        }}");
        }
        let _ = writeln!(out, "    }}");
        let _ = writeln!(out);
    }

    // 5. Emit typed Props struct + builder methods + binary CommandBufferBuilder encoder
    let _ = writeln!(out, "    #[derive(Debug, Clone, PartialEq, Default)]");
    let _ = writeln!(out, "    pub struct {pascal}Props {{");
    for prop in &spec.props {
        if let Some(doc) = &prop.doc {
            for line in doc.lines() {
                let _ = writeln!(out, "        /// {}", sanitize_single_line_comment(line));
            }
        }
        let field = rust_ident(&prop.name);
        let ty = rust_prop_type(&pascal, &prop.name, &prop.prop_type);
        if prop.optional || prop.nullable {
            let _ = writeln!(out, "        pub {field}: Option<{ty}>,");
        } else {
            let _ = writeln!(out, "        pub {field}: {ty},");
        }
    }
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out);

    let _ = writeln!(out, "    impl {pascal}Props {{");
    let _ = writeln!(out, "        pub fn new() -> Self {{");
    let _ = writeln!(out, "            Self::default()");
    let _ = writeln!(out, "        }}");

    for prop in &spec.props {
        let field = rust_ident(&prop.name);
        let method = format!("with_{}", to_snake_case(&prop.name));
        let ty = rust_prop_type(&pascal, &prop.name, &prop.prop_type);
        let _ = writeln!(out);
        if prop.optional || prop.nullable {
            let _ = writeln!(
                out,
                "        pub fn {method}(mut self, value: impl Into<{ty}>) -> Self {{"
            );
            let _ = writeln!(out, "            self.{field} = Some(value.into());");
            let _ = writeln!(out, "            self");
            let _ = writeln!(out, "        }}");
        } else {
            let _ = writeln!(
                out,
                "        pub fn {method}(mut self, value: impl Into<{ty}>) -> Self {{"
            );
            let _ = writeln!(out, "            self.{field} = value.into();");
            let _ = writeln!(out, "            self");
            let _ = writeln!(out, "        }}");
        }
    }

    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "        /// Emits `CreateNode(ComponentKind::Custom, Some(\"{}\"))` and all typed raw props.",
        sanitize_single_line_comment(&spec.component_name)
    );
    let _ = writeln!(
        out,
        "        pub fn mount(&self, builder: &mut CommandBufferBuilder, node_id: NodeId) {{"
    );
    let _ = writeln!(
        out,
        "            builder.create_node(node_id, ComponentKind::Custom, Some(COMPONENT_NAME));"
    );
    let _ = writeln!(out, "            self.encode_props(builder, node_id);");
    if !spec.events.is_empty() {
        let _ = writeln!(out, "            builder.set_event_mask(node_id, EventMask::CUSTOM);");
    }
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "        /// Writes all configured props into `builder` via `RawPropValue` / binary `NveBinValue`."
    );
    let _ = writeln!(
        out,
        "        pub fn encode_props(&self, builder: &mut CommandBufferBuilder, node_id: NodeId) {{"
    );
    for prop in &spec.props {
        let field = rust_ident(&prop.name);
        let key = escape_c_like_string(&prop.name);
        if prop.optional || prop.nullable {
            let _ = writeln!(out, "            if let Some(ref val) = self.{field} {{");
            let expr = rust_to_raw_prop_expr("val", &prop.prop_type, true);
            let _ = writeln!(
                out,
                "                builder.set_raw_prop(node_id, \"{key}\", &{expr});"
            );
            let _ = writeln!(out, "            }}");
        } else {
            let expr = rust_to_raw_prop_expr(&format!("self.{field}"), &prop.prop_type, false);
            let _ = writeln!(
                out,
                "            builder.set_raw_prop(node_id, \"{key}\", &{expr});"
            );
        }
    }
    let _ = writeln!(out, "        }}");
    let _ = writeln!(out, "    }}");

    // 6. Native Commands (encoded as compact binary `NveBinValue` maps)
    if !spec.commands.is_empty() {
        let _ = writeln!(out);
        let _ = writeln!(out, "    /// Imperative native commands (`codegenNativeCommands`).");
        let _ = writeln!(out, "    pub mod commands {{");
        let _ = writeln!(out, "        use super::*;");
        for cmd in &spec.commands {
            let fn_name = rust_ident(&cmd.name);
            let mut sig = String::from("builder: &mut CommandBufferBuilder, node_id: NodeId");
            for p in &cmd.params {
                let pname = rust_ident(&p.name);
                let pty = rust_simple_type(&p.param_type);
                let _ = write!(sig, ", {pname}: {pty}");
            }
            let _ = writeln!(out);
            let _ = writeln!(out, "        pub fn {fn_name}({sig}) {{");
            if cmd.params.is_empty() {
                let _ = writeln!(
                    out,
                    "            builder.dispatch_command(node_id, \"{}\", &[]);",
                    escape_c_like_string(&cmd.name)
                );
            } else {
                emit_rust_bin_map_payload(&mut out, &cmd.params, "            ", false);
                let _ = writeln!(
                    out,
                    "            builder.dispatch_command(node_id, \"{}\", &payload);",
                    escape_c_like_string(&cmd.name)
                );
            }
            let _ = writeln!(out, "        }}");
        }
        let _ = writeln!(out, "    }}");
    }

    let _ = writeln!(out, "}}");
    out
}

pub(crate) fn emit_turbomodule_rust(spec: &TurboModuleSpec, mod_name: &str) -> String {
    let pascal = to_pascal_case(&spec.module_name);
    let mut out = String::with_capacity(2048);

    let _ = writeln!(
        out,
        "// @generated by nve-codegen (`import_rn`) from React Native TurboModule `{}`.",
        sanitize_single_line_comment(&spec.module_name)
    );
    let _ = writeln!(out, "#![allow(dead_code, clippy::all)]");
    let _ = writeln!(out);
    let _ = writeln!(out, "pub mod {mod_name} {{");
    let _ = writeln!(
        out,
        "    use nve_abi::{{encode_bin_value_to_vec, CommandBufferBuilder, NodeId, NveMapEntry, NveValue}};"
    );
    let _ = writeln!(out);
    let _ = writeln!(
        out,
        "    pub const MODULE_NAME: &str = \"{}\";",
        escape_c_like_string(&spec.module_name)
    );
    let _ = writeln!(out, "    pub const ENFORCING: bool = {};", spec.enforcing);
    let _ = writeln!(out);

    let _ = writeln!(
        out,
        "    /// Typed zero-JS host interface for TurboModule `{}`.",
        sanitize_single_line_comment(&spec.module_name)
    );
    let _ = writeln!(out, "    pub trait {pascal}Module {{");
    for method in &spec.methods {
        if let Some(doc) = &method.doc {
            for line in doc.lines() {
                let _ = writeln!(out, "        /// {}", sanitize_single_line_comment(line));
            }
        }
        let mname = rust_ident(&method.name);
        let mut params = String::from("&self");
        for p in &method.params {
            let pname = rust_ident(&p.name);
            let pty = rust_simple_type(&p.param_type);
            if p.optional {
                let _ = write!(params, ", {pname}: Option<{pty}>");
            } else {
                let _ = write!(params, ", {pname}: {pty}");
            }
        }
        let ret = rust_simple_type(&method.return_type);
        if ret == "()" {
            let _ = writeln!(out, "        fn {mname}({params});");
        } else {
            let _ = writeln!(out, "        fn {mname}({params}) -> {ret};");
        }
    }
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out);

    let _ = writeln!(
        out,
        "    /// Binary command-buffer bridge client dispatching TurboModule calls via `Command::DispatchCommand`."
    );
    let _ = writeln!(out, "    pub struct {pascal}Bridge;");
    let _ = writeln!(out);
    let _ = writeln!(out, "    impl {pascal}Bridge {{");
    for method in &spec.methods {
        let mname = rust_ident(&method.name);
        let mut params = String::from("builder: &mut CommandBufferBuilder, node_id: NodeId");
        for p in &method.params {
            let pname = rust_ident(&p.name);
            let pty = rust_simple_type(&p.param_type);
            if p.optional {
                let _ = write!(params, ", {pname}: Option<{pty}>");
            } else {
                let _ = write!(params, ", {pname}: {pty}");
            }
        }
        let _ = writeln!(out, "        pub fn {mname}({params}) {{");
        if method.params.is_empty() {
            let _ = writeln!(
                out,
                "            builder.dispatch_command(node_id, \"{}.{}\", &[]);",
                escape_c_like_string(&spec.module_name),
                escape_c_like_string(&method.name)
            );
        } else {
            emit_rust_bin_map_payload(&mut out, &method.params, "            ", true);
            let _ = writeln!(
                out,
                "            builder.dispatch_command(node_id, \"{}.{}\", &payload);",
                escape_c_like_string(&spec.module_name),
                escape_c_like_string(&method.name)
            );
        }
        let _ = writeln!(out, "        }}");
    }
    let _ = writeln!(out, "    }}");
    let _ = writeln!(out, "}}");
    out
}

